            case 125: return new[] { "A thick piece of meat.\\nIt gives strength to adventurers\\nwho are exhausted from hunger.\\nRestores HP <color=#00FF7F><b>+30%</b></color>", "두툼한 고기 조각.\\n배고픔에 지친 모험가에게\\n힘이 나게 해준다.\\n체력회복 <color=#00FF7F><b>+30%</b></color>", "A thick piece of meat.\\nIt gives strength to adventurers\\nwho are exhausted from hunger.\\nRestores HP <color=#00FF7F><b>+30%</b></color>", "分厚い肉の塊。\\n空腹で疲れ果てた冒険者に\\n力を与えてくれる。\\n体力回復 <color=#00FF7F><b>+30%</b></color>", "厚实的肉块。\\n能让饿得筋疲力尽的冒险者\\n重新充满力气。\\n生命值恢复 <color=#00FF7F><b>+30%</b></color>" }[language >= 0 && language <= 4 ? language : 0];
            case 126: return new[] { "A potion in a small bottle.\\nIt is made by boiling common herbs^\\nbut it quickly restores health.\\nRestores HP <color=#00FF7F><b>+40%</b></color>", "작은 병에 담긴 물약.\\n흔한 약초를 달여 만들었지만\\n빠르게 체력을 회복시켜준다.\\n체력회복 <color=#00FF7F><b>+40%</b></color>", "A potion in a small bottle.\\nIt is made by boiling common herbs^\\nbut it quickly restores health.\\nRestores HP <color=#00FF7F><b>+40%</b></color>", "小瓶に入ったポーション。\\nありふれた薬草を煎じたものだが\\nすばやく体力を回復してくれる。\\n体力回復 <color=#00FF7F><b>+40%</b></color>", "装在小瓶里的药水。\\n虽然只是用常见草药熬成的\\n却能迅速恢复生命值。\\n生命值恢复 <color=#00FF7F><b>+40%</b></color>" }[language >= 0 && language <= 4 ? language : 0];
            case 127: return new[] { "A potion in a generous bottle.\\nIt is traded at a high price because it uses expensive herbs.\\nIt can instantly restore even exhausted adventurers.\\nRestores HP <color=#00FF7F><b>+50%</b></color>", "넉넉한 병에 담긴 물약.\\n비싼 약초가 사용되어 비싸게 거래된다.\\n지친 모험가도 즉시 회복시켜줄 수 있다.\\n체력회복 <color=#00FF7F><b>+50%</b></color>", "A potion in a generous bottle.\\nIt is traded at a high price because it uses expensive herbs.\\nIt can instantly restore even exhausted adventurers.\\nRestores HP <color=#00FF7F><b>+50%</b></color>", "大きめの瓶に入ったポーション。\\n高価な薬草を使うため高値で取引される。\\n疲れ果てた冒険者もたちまち回復させる。\\n体力回復 <color=#00FF7F><b>+50%</b></color>", "装在大瓶里的药水。\\n用了名贵的草药，因此售价不菲。\\n能让精疲力竭的冒险者立刻恢复。\\n生命值恢复 <color=#00FF7F><b>+50%</b></color>" }[language >= 0 && language <= 4 ? language : 0];
            case 128: return new[] { "Specially brewed by an apothecary from rare herbs^\\nit gets even the fainted back on their feet.\\nRestores HP <color=#00FF7F><b>+60%</b></color>", "귀한 약초로 약사가 특별하게 제조하여\\n실신한 사람도 벌떡 일어나게 만든다.\\n체력회복 <color=#00FF7F><b>+60%</b></color>", "Specially brewed by an apothecary from rare herbs^\\nit gets even the fainted back on their feet.\\nRestores HP <color=#00FF7F><b>+60%</b></color>", "薬師が貴重な薬草で特別に調合したもの。\\n気を失った者さえ飛び起きるという。\\n体力回復 <color=#00FF7F><b>+60%</b></color>", "药师用珍贵草药特别调制而成，\\n连昏倒的人都能一下子跳起来。\\n生命值恢复 <color=#00FF7F><b>+60%</b></color>" }[language >= 0 && language <= 4 ? language : 0];
            case 129: return new[] { "A potion with a mysterious glow.\\nIt is a miraculous potion that can even revive the dead.\\nPharmacists are racing to find the recipe.\\nRestores HP <color=#00FF7F><b>+100%</b></color>", "신비로운 빛이 나는 물약.\\n죽은 사람도 살린다는 기적의 물약으로\\n제조법을 찾기 위한 약사들이 앞다퉈 연구 중이다.\\n체력회복 <color=#00FF7F><b>+100%</b></color>", "A potion with a mysterious glow.\\nIt is a miraculous potion that can even revive the dead.\\nPharmacists are racing to find the recipe.\\nRestores HP <color=#00FF7F><b>+100%</b></color>", "神秘的な光を放つポーション。\\n死者さえ蘇らせるという奇跡の薬で\\n薬師たちが競って製法を研究している。\\n体力回復 <color=#00FF7F><b>+100%</b></color>", "散发着神秘光芒的药水。\\n传说是能起死回生的奇迹之药\\n药师们正争相研究它的配方。\\n生命值恢复 <color=#00FF7F><b>+100%</b></color>" }[language >= 0 && language <= 4 ? language : 0];
            case 130: return new[] { "A magic stone with the power of destruction.\\nAncient letters engraved with magic are shining.\\nThe power of destruction rises from within.", "파괴의 힘이 담긴 마석.\\n마법으로 새겨진 고대 문자가 빛나고 있다.\\n내면에서 파괴의 힘이 솟아난다.", "A magic stone with the power of destruction.\\nAncient letters engraved with magic are shining.\\nThe power of destruction rises from within.", "破壊の力を宿した魔石。\\n魔法で刻まれた古代文字が輝いている。\\n内から破壊の力が湧き上がる。", "蕴含破坏之力的魔石。\\n以魔法刻下的古代文字闪闪发光。\\n破坏之力自体内涌出。" }[language >= 0 && language <= 4 ? language : 0];
            case 131: return new[] { "A magic stone with the power of endurance.\\nAncient letters engraved with magic are shining.\\nThe power of endurance rises from within.", "인내의 힘이 담긴 마석.\\n마법으로 새겨진 고대 문자가 빛나고 있다.\\n내면에서 인내의 힘이 솟아난다.", "A magic stone with the power of endurance.\\nAncient letters engraved with magic are shining.\\nThe power of endurance rises from within.", "忍耐の力を宿した魔石。\\n魔法で刻まれた古代文字が輝いている。\\n内から忍耐の力が湧き上がる。", "蕴含忍耐之力的魔石。\\n以魔法刻下的古代文字闪闪发光。\\n忍耐之力自体内涌出。" }[language >= 0 && language <= 4 ? language : 0];
            case 132: return new[] { "A magic stone with the power of life.\\nAncient letters engraved with magic are shining.\\nThe power of life rises from within.", "생명의 힘이 담긴 마석.\\n마법으로 새겨진 고대 문자가 빛나고 있다.\\n내면에서 생명의 힘이 솟아난다.", "A magic stone with the power of life.\\nAncient letters engraved with magic are shining.\\nThe power of life rises from within.", "生命の力を宿した魔石。\\n魔法で刻まれた古代文字が輝いている。\\n内から生命の力が湧き上がる。", "蕴含生命之力的魔石。\\n以魔法刻下的古代文字闪闪发光。\\n生命之力自体内涌出。" }[language >= 0 && language <= 4 ? language : 0];
            case 4002: return new[] { "Ranger Boots", "레인저 부츠", "Ranger Boots", "レンジャーブーツ", "游侠之靴" }[language >= 0 && language <= 4 ? language : 0];
            case 4003: return new[] { "Spirit Wind Boots", "스피리트 윈드 부츠", "Spirit Wind Boots", "風霊のブーツ", "风灵之靴" }[language >= 0 && language <= 4 ? language : 0];
            case 4004: return new[] { "Angel Wing Boots", "엔젤 윙 부츠", "Angel Wing Boots", "天使の翼のブーツ", "天使之翼靴" }[language >= 0 && language <= 4 ? language : 0];
            case 4005: return new[] { "Tartaros Boots", "타르타로스 부츠", "Tartaros Boots", "タルタロスブーツ", "塔尔塔罗斯之靴" }[language >= 0 && language <= 4 ? language : 0];
            case 4006: return new[] { "Boots with guaranteed mobility.\\nIt increases movement speed by giving you a light step.", "활동성이 보장된 부츠.\\n가벼운 발걸음을 선사하여 이동 속도를 증가시켜준다.", "Boots with guaranteed mobility.\\nIt increases movement speed by giving you a light step.", "動きやすさ抜群のブーツ。\\n足取りを軽くし、移動速度を上げてくれる。", "行动灵活自如的靴子。\\n让脚步变得轻盈，提升移动速度。" }[language >= 0 && language <= 4 ? language : 0];
            case 4007: return new[] { "Boots imbued with the spirit of the wind.\\nYou can move very lightly with the magic of the wind.", "바람의 정령이 깃든 부츠.\\n바람의 마법으로 매우 가볍게 이동할 수 있다.", "Boots imbued with the spirit of the wind.\\nYou can move very lightly with the magic of the wind.", "風の精霊が宿るブーツ。\\n風の魔法でとても軽やかに移動できる。", "附有风之精灵的靴子。\\n借助风之魔法，可以极其轻盈地移动。" }[language >= 0 && language <= 4 ? language : 0];
            case 4008: return new[] { "Boots with angel wings.\\nThe wings of a noble angel will lead you to where you want to go.", "천사의 날개가 달린 부츠.\\n고귀한 천사의 날개가 원하는 곳으로 인도한다.", "Boots with angel wings.\\nThe wings of a noble angel will lead you to where you want to go.", "天使の翼がついたブーツ。\\n気高き天使の翼が望む場所へと導いてくれる。", "装有天使之翼的靴子。\\n高贵的天使之翼会引领你去往想去的地方。" }[language >= 0 && language <= 4 ? language : 0];
            case 4009: return new[] { "Boots of Tartarus^ the abyssal underworld.\\nThey carry you without a single step^ at a speed from another dimension.", "심연의 명계 타르타로스의 부츠.\\n걷지 않아도 알아서 움직이며^ 그 속도는 차원을 달리한다.", "Boots of Tartarus^ the abyssal underworld.\\nThey carry you without a single step^ at a speed from another dimension.", "深淵の冥界タルタロスのブーツ。\\n歩かずとも勝手に動き、その速さは次元が違う。", "深渊冥界塔尔塔罗斯的靴子。\\n无需迈步便会自行移动，其速度已是另一个次元。" }[language >= 0 && language <= 4 ? language : 0];
            case 4010: return new[] { "Sandglass Necklace", "모래시계 목걸이", "Sandglass Necklace", "砂時計の首飾り", "沙漏项链" }[language >= 0 && language <= 4 ? language : 0];
            case 4011: return new[] { "Aeon's Ring", "에온의 고리", "Aeon's Ring", "アイオーンの輪", "埃昂之环" }[language >= 0 && language <= 4 ? language : 0];
            case 4012: return new[] { "Circe's Pendulum", "키르케의 시계추", "Circe's Pendulum", "キルケーの振り子", "喀耳刻的钟摆" }[language >= 0 && language <= 4 ? language : 0];
            case 4013: return new[] { "Chronos's Clock", "크로노스의 시계", "Chronos's Clock", "クロノスの時計", "克洛诺斯之钟" }[language >= 0 && language <= 4 ? language : 0];
            case 4014: return new[] { "A necklace made from a magic hourglass.\\nUtilizes the flow of time to advance battle time.", "마법의 모래시계로 만든 목걸이.\\n시간의 흐름을 이용하여 전투 시간을 앞당긴다.", "A necklace made from a magic hourglass.\\nUtilizes the flow of time to advance battle time.", "魔法の砂時計で作った首飾り。\\n時の流れを利用して戦闘の時間を早める。", "用魔法沙漏制成的项链。\\n利用时间的流动，加快战斗进程。" }[language >= 0 && language <= 4 ? language : 0];
            case 4015: return new[] { "A necklace made from the ring of the time traveler Aeon.\\nControls the flow of time to quickly advance battle time.", "시간 여행자인 에온의 고리로 만든 목걸이.\\n시간의 흐름을 제어하여 전투 시간을 신속하게 앞당긴다.", "A necklace made from the ring of the time traveler Aeon.\\nControls the flow of time to quickly advance battle time.", "時の旅人アイオーンの輪で作った首飾り。\\n時の流れを制御し、戦闘の時間を素早く進める。", "用时间旅者埃昂之环制成的项链。\\n掌控时间的流动，迅速加快战斗进程。" }[language >= 0 && language <= 4 ? language : 0];
            case 4016: return new[] { "A necklace made from the pendulum of the witch Circe.\\nDistorts the flow of time to quickly advance battle time.", "마녀 키르케의 시계추로 만든 목걸이.\\n시간의 흐름을 변형시켜 전투시간을 빠르게 앞당긴다.", "A necklace made from the pendulum of the witch Circe.\\nDistorts the flow of time to quickly advance battle time.", "魔女キルケーの振り子で作った首飾り。\\n時の流れを歪め、戦闘の時間を速く進める。", "用魔女喀耳刻的钟摆制成的项链。\\n扭曲时间的流动，大幅加快战斗进程。" }[language >= 0 && language <= 4 ? language : 0];
            case 4017: return new[] { "A necklace made from the clock of Chronos^ the god of time.\\nReconstructs the flow of time to rapidly advance battle time.", "시간의 신 크로노스의 시계로 만든 목걸이.\\n시간의 흐름을 재구축하여 전투시간을 급격하게 앞당긴다.", "A necklace made from the clock of Chronos^ the god of time.\\nReconstructs the flow of time to rapidly advance battle time.", "時の神クロノスの時計で作った首飾り。\\n時の流れを再構築し、戦闘の時間を一気に進める。", "用时间之神克洛诺斯之钟制成的项链。\\n重构时间的流动，急剧加快战斗进程。" }[language >= 0 && language <= 4 ? language : 0];
            case 4019: return new[] { "Aphestion", "애페스티온", "Aphestion", "アフェスティオン", "阿菲斯提昂" }[language >= 0 && language <= 4 ? language : 0];
            case 4020: return new[] { "Valefont", "발레폰트", "Valefont", "ヴァレフォント", "瓦勒丰特" }[language >= 0 && language <= 4 ? language : 0];
