            case 4023: return new[] { "Arcandis", "아르칸디스", "Arcandis", "アルカンディス", "阿尔坎迪斯" }[language >= 0 && language <= 4 ? language : 0];
            case 4024: return new[] { "Excalibur", "엑스칼리버", "Excalibur", "エクスカリバー", "王者之剑" }[language >= 0 && language <= 4 ? language : 0];
            case 4025: return new[] { "Phoenixia", "피닉시아", "Phoenixia", "フェニキシア", "菲尼克西亚" }[language >= 0 && language <= 4 ? language : 0];
            case 4026: return new[] { "Raitanion", "라이타니온", "Raitanion", "ライタニオン", "雷塔尼昂" }[language >= 0 && language <= 4 ? language : 0];
            case 4027: return new[] { "Umbranox", "움브라노크스", "Umbranox", "ウンブラノクス", "安布拉诺克斯" }[language >= 0 && language <= 4 ? language : 0];
            case 4028: return new[] { "Ragnar Break", "라그나브레이크", "Ragnar Break", "ラグナブレイク", "拉格纳布雷克" }[language >= 0 && language <= 4 ? language : 0];
            case 4030: return new[] { "Sword of Prayer\\nA sword made by an ancient priest to perform a sacred mission^\\nit grants the user basic protection and blessings.", "기도의 검\\n신성한 임무를 수행하기 위해 고대 사제가 제작한 검으로^\\n사용자에게 기본적인 보호와 축복을 내린다.", "Sword of Prayer\\nA sword made by an ancient priest to perform a sacred mission^\\nit grants the user basic protection and blessings.", "祈りの剣\\n神聖な使命を果たすため古代の司祭が作った剣で、\\n使い手に基本的な加護と祝福を授ける。", "祈祷之剑\\n古代祭司为完成神圣使命而打造的剑，\\n能赐予使用者基本的守护与祝福。" }[language >= 0 && language <= 4 ? language : 0];
            case 4031: return new[] { "Sword of the Hero\\n100 years ago^ it slew the monster plaguing the village\\nand came to be named after that hero.", "영웅의 검\\n100년 전^ 마을을 괴롭히던 괴물을 무찌르고\\n그 영웅의 이름을 따서 불리게 되었다.", "Sword of the Hero\\n100 years ago^ it slew the monster plaguing the village\\nand came to be named after that hero.", "英雄の剣\\n100年前、村を苦しめていた怪物を討ち倒し\\nその英雄の名で呼ばれるようになった。", "英雄之剑\\n百年前曾讨伐为祸村庄的怪物\\n从此便以那位英雄之名相称。" }[language >= 0 && language <= 4 ? language : 0];
            case 4032: return new[] { "Sword of the Moon\\nA sacred sword made of silver imbued with moonlight by the goddess of the moon to defeat the monsters.", "달의 검\\n달의 여신이 마물을 물리치기 위해^\\n달빛이 깃든 은으로 만든 성스러운 검이다.", "Sword of the Moon\\nA sacred sword made of silver imbued with moonlight by the goddess of the moon to defeat the monsters.", "月の剣\\n月の女神が魔物を退けるため、\\n月光を宿した銀で作った聖なる剣。", "月之剑\\n月之女神为击退魔物，\\n用蕴含月光的白银打造的圣剑。" }[language >= 0 && language <= 4 ? language : 0];
            case 4033: return new[] { "Dragon Sword\\nMade from the teeth of an ancient dragon^ it breathes dragon fire\\nand was the weapon of a legendary dragon hunter.", "용의 검\\n고대의 용의 이빨로 만들어져^ 용의 불꽃을\\n내뿜을 수 있는 전설적인 용 사냥꾼의 무기이다.", "Dragon Sword\\nMade from the teeth of an ancient dragon^ it breathes dragon fire\\nand was the weapon of a legendary dragon hunter.", "竜の剣\\n古代竜の牙から作られ、竜の炎を\\n吐き出せる伝説の竜狩りの武器。", "龙之剑\\n以远古巨龙的牙齿打造，能喷吐龙焰\\n是传说中屠龙猎人的武器。" }[language >= 0 && language <= 4 ? language : 0];
            case 4034: return new[] { "Magic Sword\\nA powerful magical sword with a jewel imbued with an unknown magic\\nthat amplifies the user's abilities.", "마법의 검\\n정체불명의 마법이 깃든 보석이 박혀 있어^\\n사용자의 능력을 증폭시키는 강력한 마법 검이다.", "Magic Sword\\nA powerful magical sword with a jewel imbued with an unknown magic\\nthat amplifies the user's abilities.", "魔法の剣\\n正体不明の魔法を宿した宝石がはめ込まれ、\\n使い手の力を増幅させる強力な魔法剣。", "魔法之剑\\n镶嵌着蕴含不明魔法的宝石，\\n是能增幅使用者能力的强大魔法剑。" }[language >= 0 && language <= 4 ? language : 0];
            case 4035: return new[] { "Light Sword\\nMade by the Guardian of Light^ it has the power to defeat dark beings\\nand protect justice.", "빛의 검\\n빛의 수호자에 의해 만들어져 어둠의 존재들을\\n물리치고 정의를 수호하는 힘을 지녔다.", "Light Sword\\nMade by the Guardian of Light^ it has the power to defeat dark beings\\nand protect justice.", "光の剣\\n光の守護者によって作られ、闇の存在を\\n退け正義を守る力を持つ。", "光之剑\\n由光之守护者打造，拥有击退黑暗存在、\\n守护正义的力量。" }[language >= 0 && language <= 4 ? language : 0];
            case 4036: return new[] { "Resurrection Sword\\nMade from the feathers of the phoenix^ it has the power of resurrection that allows the user to rise again in flames even if they fall.", "부활의 검\\n불사조의 깃털로 만들어져^ 사용자가 쓰러져도\\n불꽃 속에서 다시 일어날 수 있는 부활의 힘을 지닌다.", "Resurrection Sword\\nMade from the feathers of the phoenix^ it has the power of resurrection that allows the user to rise again in flames even if they fall.", "復活の剣\\n不死鳥の羽根から作られ、使い手が倒れても\\n炎の中から再び立ち上がれる復活の力を持つ。", "复活之剑\\n以不死鸟的羽毛打造，即使使用者倒下\\n也能凭复活之力从火焰中再度站起。" }[language >= 0 && language <= 4 ? language : 0];
            case 4037: return new[] { "Thunder Sword\\nA sword forged from the thunderbolts of the god of thunder^ it can inflict deadly lightning power on enemies.", "천둥의 검\\n천둥신이 내린 벼락으로 단련한 검으로^\\n적에게 치명적인 번개의 힘을 가할 수 있다.", "Thunder Sword\\nA sword forged from the thunderbolts of the god of thunder^ it can inflict deadly lightning power on enemies.", "雷の剣\\n雷神が落とした稲妻で鍛えた剣で、\\n敵に致命的な雷の力を叩き込める。", "雷霆之剑\\n以雷神降下的霹雳锻造而成，\\n能对敌人施加致命的雷电之力。" }[language >= 0 && language <= 4 ? language : 0];
            case 4038: return new[] { "Curse Sword\\nMade from materials from the abyss of darkness^ it has the ability to absorb the life force of enemies and heal the user.", "저주의 검\\n어둠의 심연에서 나온 재료로 만들어져^\\n적의 생명력을 흡수하여 사용자를 치유하는 능력을 지녔다.", "Curse Sword\\nMade from materials from the abyss of darkness^ it has the ability to absorb the life force of enemies and heal the user.", "呪いの剣\\n闇の深淵から生まれた素材で作られ、\\n敵の生命力を吸い取って使い手を癒やす力を持つ。", "诅咒之剑\\n以来自黑暗深渊的材料打造，\\n能吸取敌人的生命力来治愈使用者。" }[language >= 0 && language <= 4 ? language : 0];
            case 4039: return new[] { "Absolute Sword\\nA legendary sword used in the war of the gods^ its power\\nis great enough to reshape the world^ and it holds many abilities.", "절대자의 검\\n신들의 전쟁에서 사용된 전설의 검으로^ 그 힘은\\n세계를 재구성할 수 있을 정도로 강력하며 다양한 능력을 가지고 있다.", "Absolute Sword\\nA legendary sword used in the war of the gods^ its power\\nis great enough to reshape the world^ and it holds many abilities.", "絶対者の剣\\n神々の戦争で使われた伝説の剣で、その力は\\n世界を作り変えるほど強大で、多彩な能力を秘めている。", "绝对者之剑\\n诸神之战中使用过的传说之剑，其力量\\n强大到足以重塑世界，并拥有多种能力。" }[language >= 0 && language <= 4 ? language : 0];
            case 4040: return new[] { "Hunter Shield", "헌터 실드", "Hunter Shield", "ハンターの盾", "猎人之盾" }[language >= 0 && language <= 4 ? language : 0];
            case 4041: return new[] { "Orc Knight Shield", "오크나이트 실드", "Orc Knight Shield", "オークナイトの盾", "兽人骑士之盾" }[language >= 0 && language <= 4 ? language : 0];
