            case 4045: return new[] { "Griffon Shield", "그리폰 실드", "Griffon Shield", "グリフォンの盾", "狮鹫之盾" }[language >= 0 && language <= 4 ? language : 0];
            case 4046: return new[] { "Guardian Shield", "가디언 실드", "Guardian Shield", "ガーディアンの盾", "守护者之盾" }[language >= 0 && language <= 4 ? language : 0];
            case 4047: return new[] { "Triton Shield", "트리톤 실드", "Triton Shield", "トリトンの盾", "特里同之盾" }[language >= 0 && language <= 4 ? language : 0];
            case 4048: return new[] { "Shadow Shield", "쉐도우 실드", "Shadow Shield", "影の盾", "暗影之盾" }[language >= 0 && language <= 4 ? language : 0];
            case 4049: return new[] { "Eldritch Shield", "엘드리치 실드", "Eldritch Shield", "エルドリッチの盾", "埃尔德里奇之盾" }[language >= 0 && language <= 4 ? language : 0];
            case 4050: return new[] { "A shield mainly used by hunters who hunt wild beasts.\\nIt is small and light^ so it can block simple attacks from enemies.", "야수를 사냥하는 헌터들이 주로 사용하던 방패.\\n작고 가벼워 적의 간단한 공격은 막을 수 있다.", "A shield mainly used by hunters who hunt wild beasts.\\nIt is small and light^ so it can block simple attacks from enemies.", "獣を狩るハンターたちが主に使っていた盾。\\n小さく軽いが、敵の単純な攻撃なら防げる。", "猎人们狩猎野兽时常用的盾牌。\\n小巧轻便，能挡住敌人的简单攻击。" }[language >= 0 && language <= 4 ? language : 0];
            case 4051: return new[] { "A shield used by orc warriors.\\nIt is made roughly^ but its defensive capabilities are guaranteed.", "오크 전사가 사용하던 방패.\\n만듦새는 투박하지만 방어 능력은 보장한다.", "A shield used by orc warriors.\\nIt is made roughly^ but its defensive capabilities are guaranteed.", "オークの戦士が使っていた盾。\\n作りは粗いが、守りの力は確かだ。", "兽人战士使用过的盾牌。\\n做工虽粗糙，防御能力却有保障。" }[language >= 0 && language <= 4 ? language : 0];
            case 4052: return new[] { "A shield as solid as a giant iron wall.\\nIt blocks any attack and maximizes the owner's defensive capabilities.", "거대한 철의 벽처럼 단단한 방패.\\n어떠한 공격도 막아내며 소유자의 방어력을 극대화한다.", "A shield as solid as a giant iron wall.\\nIt blocks any attack and maximizes the owner's defensive capabilities.", "巨大な鉄の壁のように頑丈な盾。\\nあらゆる攻撃を防ぎ、持ち主の防御力を最大限に高める。", "如巨大铁墙般坚固的盾牌。\\n能挡下任何攻击，将持有者的防御力提升到极致。" }[language >= 0 && language <= 4 ? language : 0];
            case 4053: return new[] { "A shield imbued with the energy of forest spirits.\\nIt has the effect of healing and protecting wounds with the power of nature.", "숲의 정령들의 기운을 머금은 방패.\\n자연의 힘으로 상처를 치유하고 보호하는 효과가 있다.", "A shield imbued with the energy of forest spirits.\\nIt has the effect of healing and protecting wounds with the power of nature.", "森の精霊たちの気を宿した盾。\\n自然の力で傷を癒やし、身を守る効果がある。", "蕴含森林精灵气息的盾牌。\\n能借自然之力治愈伤口、守护持有者。" }[language >= 0 && language <= 4 ? language : 0];
            case 4054: return new[] { "A shield made by dwarves from the mysterious ore^ Mithril.\\nIt is very light^ but boasts excellent defensive capabilities.", "드워프가 신비한 광석^ 미스릴로 만든 방패.\\n매우 가벼우면서도 뛰어난 방어력을 자랑한다.", "A shield made by dwarves from the mysterious ore^ Mithril.\\nIt is very light^ but boasts excellent defensive capabilities.", "ドワーフが神秘の鉱石ミスリルで作った盾。\\nとても軽いのに、優れた防御力を誇る。", "矮人用神秘矿石秘银打造的盾牌。\\n极为轻巧，却拥有出色的防御力。" }[language >= 0 && language <= 4 ? language : 0];
            case 4055: return new[] { "A shield decorated with the wings and claws of a sacred griffon.\\nIt has mobility and protection that encompasses the sky and the ground.", "신성한 그리폰의 날개와 갈퀴로 장식된 방패.\\n하늘과 땅을 아우르는 기동성과 보호력을 가지고 있다.", "A shield decorated with the wings and claws of a sacred griffon.\\nIt has mobility and protection that encompasses the sky and the ground.", "神聖なグリフォンの翼と鉤爪で飾られた盾。\\n天と地をまたにかける機動力と守りの力を持つ。", "以神圣狮鹫的翅膀与利爪装饰的盾牌。\\n兼具纵横天地的机动性与防护力。" }[language >= 0 && language <= 4 ? language : 0];
            case 4056: return new[] { "A shield used by ancient guardians.\\nIt promises absolute protection for its owner.", "고대 가디언이 사용했던 방패.\\n주인에 대한 절대적인 수호를 약속한다.", "A shield used by ancient guardians.\\nIt promises absolute protection for its owner.", "古代のガーディアンが使っていた盾。\\n持ち主に絶対の守護を約束する。", "古代守护者使用过的盾牌。\\n向主人许下绝对守护的誓约。" }[language >= 0 && language <= 4 ? language : 0];
            case 4057: return new[] { "A shield used by Triton^ the god of the sea.\\nIt has the power of water and the sea^ and protects with the protection of the god.", "바다의 신 트리톤이 사용하던 방패.\\n물과 바다의 힘을 가지고 있으며^ 신의 가호로 보호한다.", "A shield used by Triton^ the god of the sea.\\nIt has the power of water and the sea^ and protects with the protection of the god.", "海の神トリトンが使っていた盾。\\n水と海の力を宿し、神の加護で守ってくれる。", "海神特里同使用过的盾牌。\\n蕴含水与海之力，以神的庇护守护持有者。" }[language >= 0 && language <= 4 ? language : 0];
            case 4058: return new[] { "An incredible shield made of darkness.\\nIt is said that the owner can move stealthily in the shadows.", "어둠을 재료로 만들었다는 믿기 힘든 방패.\\n소유자는 그림자 속에서 은밀하게 움직일 수 있다고 전해진다.", "An incredible shield made of darkness.\\nIt is said that the owner can move stealthily in the shadows.", "闇を素材に作ったという、信じがたい盾。\\n持ち主は影の中を密かに動けると伝えられる。", "据说以黑暗为材料打造，令人难以置信的盾牌。\\n相传持有者能在阴影中悄然行动。" }[language >= 0 && language <= 4 ? language : 0];
            case 4059: return new[] { "A shield imbued with the power of the undead wizard Eldritch.\\nA powerful magical power swirls around^ so only those who are worthy can use it.", "언데드 마법사 엘드리치의 힘이 깃든 방패.\\n강대한 마력이 휘몰아치고 있어 그에 걸맞은 자가 아니면 사용할 수 없다.", "A shield imbued with the power of the undead wizard Eldritch.\\nA powerful magical power swirls around^ so only those who are worthy can use it.", "アンデッドの魔法使いエルドリッチの力が宿る盾。\\n強大な魔力が渦巻き、ふさわしい者でなければ扱えない。", "蕴含亡灵法师埃尔德里奇之力的盾牌。\\n强大的魔力在其中翻涌，唯有配得上它的人才能使用。" }[language >= 0 && language <= 4 ? language : 0];
            case 5000: return new[] { "Forest of Demons", "마물의 숲", "Forest of Demons", "魔物の森", "魔物之森" }[language >= 0 && language <= 4 ? language : 0];
            case 5001: return new[] { "Inside the Forest of Demons", "마물의 숲 안쪽", "Inside the Forest of Demons", "魔物の森の奥", "魔物之森深处" }[language >= 0 && language <= 4 ? language : 0];
