            case 10001: return new[] { "Mango Slime", "망고 슬라임", "Mango Slime", "マンゴースライム", "芒果史莱姆" }[language >= 0 && language <= 4 ? language : 0];
            case 10002: return new[] { "Crow", "크로우", "Crow", "クロウ", "乌鸦" }[language >= 0 && language <= 4 ? language : 0];
            case 10003: return new[] { "Forest Spirit", "숲의 정령", "Forest Spirit", "森の精霊", "森林精灵" }[language >= 0 && language <= 4 ? language : 0];
