            case 10006: return new[] { "Blunt Slime", "둔기 슬라임", "Blunt Slime", "鈍器スライム", "钝器史莱姆" }[language >= 0 && language <= 4 ? language : 0];
            case 10007: return new[] { "Dagger Slime", "단검 슬라임", "Dagger Slime", "短剣スライム", "短剑史莱姆" }[language >= 0 && language <= 4 ? language : 0];
            case 10008: return new[] { "Shield Slime", "방패 슬라임", "Shield Slime", "盾スライム", "盾牌史莱姆" }[language >= 0 && language <= 4 ? language : 0];
            case 20000: return new[] { "A slime with a bright^ transparent green color.\\nIt mainly lives near forests^ and exudes a refreshing lime scent.\\nWhen attacked^ it refreshes the surrounding air^\\nbut at the same time^ it sprays a sticky^ acidic liquid to attack enemies.", "밝고 투명한 녹색을 띠는 슬라임.\\n주로 숲 근처에 서식하며^ 상쾌한 라임 향기를 내뿜는다.\\n공격 받을 때마다 주변 공기를 상쾌하게 만들지만^\\n동시에 끈적한 산성 액체를 뿌려 적을 공격한다.", "A slime with a bright^ transparent green color.\\nIt mainly lives near forests^ and exudes a refreshing lime scent.\\nWhen attacked^ it refreshes the surrounding air^\\nbut at the same time^ it sprays a sticky^ acidic liquid to attack enemies.", "明るく透き通った緑色のスライム。\\n主に森の近くに棲み、さわやかなライムの香りを放つ。\\n攻撃を受けるたびに周りの空気をさわやかにするが、\\n同時にねばつく酸性の液をまき散らして敵を攻撃する。", "呈明亮透明绿色的史莱姆。\\n主要栖息在森林附近，散发着清新的青柠香气。\\n每次受到攻击都会让周围的空气变得清新，\\n同时也会喷出黏稠的酸液攻击敌人。" }[language >= 0 && language <= 4 ? language : 0];
            case 20001: return new[] { "A slime that smells like yellow mango.\\nIt is usually found under mango trees^ and grows by eating ripe mangoes.\\nThe liquid that drips from its body is highly nutritious^ and causes nearby plants to grow quickly.\\nIt lures enemies with its sweet scent^ and then attacks them with sticky mucus.", "노란 망고 향을 풍기는 슬라임.\\n주로 망고 나무 아래에서 발견되며^ 익은 망고를 먹으며 자란다.\\n몸체에서 떨어진 액체는 영양분이 높아^ 주변 식물이 빠르게 자란다.\\n적을 달콤한 향기로 유인한 뒤^ 끈적한 점액으로 공격한다.", "A slime that smells like yellow mango.\\nIt is usually found under mango trees^ and grows by eating ripe mangoes.\\nThe liquid that drips from its body is highly nutritious^ and causes nearby plants to grow quickly.\\nIt lures enemies with its sweet scent^ and then attacks them with sticky mucus.", "黄色いマンゴーの香りを漂わせるスライム。\\n主にマンゴーの木の下で見つかり、熟したマンゴーを食べて育つ。\\n体から滴る液は栄養たっぷりで、周りの植物がぐんぐん育つ。\\n甘い香りで敵をおびき寄せ、ねばつく粘液で攻撃する。", "散发着黄色芒果香气的史莱姆。\\n常在芒果树下出没，以熟透的芒果为食。\\n身上滴落的液体营养丰富，能让周围的植物迅速生长。\\n它会用甜美的香气引诱敌人，再用黏稠的黏液发动攻击。" }[language >= 0 && language <= 4 ? language : 0];
            case 20002: return new[] { "A highly intelligent mutant crow that lives in the forest.\\nConsidered to be a being that announces ominous omens^ it is characterized by its black feathers and red eyes.\\nIt is adept at blocking the vision of enemies in the dark^ and finding and attacking their weak points.", "지능이 높고 숲속에 서식하는 변종 까마귀.\\n불길한 징조를 알리는 존재로 여겨지며^ 검은 깃털과 붉은 눈이 특징.\\n어둠 속에서 적의 시야를 차단하고^ 그들의 약점을 찾아내 공격하는 데 능숙하다.", "A highly intelligent mutant crow that lives in the forest.\\nConsidered to be a being that announces ominous omens^ it is characterized by its black feathers and red eyes.\\nIt is adept at blocking the vision of enemies in the dark^ and finding and attacking their weak points.", "知能が高く、森に棲む変異種のカラス。\\n不吉な前兆を告げる存在とされ、黒い羽根と赤い目が特徴。\\n闇の中で敵の視界をさえぎり、弱点を見つけて攻撃するのが得意だ。", "智力很高、栖息在森林中的变异乌鸦。\\n被视为预示不祥的存在，特征是黑色羽毛与红色眼睛。\\n擅长在黑暗中遮蔽敌人的视线，找出弱点发动攻击。" }[language >= 0 && language <= 4 ? language : 0];
            case 20003: return new[] { "Mysterious beings that protect the life of the forest.\\nThey have a green glow and look like they are one with the trees.\\nThey maintain the balance of the forest^ and protect it from outside invaders.\\nThey can use protective magic by borrowing the power of nature^ and communicate with the creatures of the forest.", "숲의 생명을 지키는 신비로운 존재.\\n초록색 빛을 띠며 나무와 동화된 모습을 하다.\\n이들은 숲의 균형을 유지하고^ 외부 침입자로부터 숲을 보호한다.\\n자연의 힘을 빌려 보호 마법을 사용할 수 있으며^ 숲속 생명체들과 교감한다.", "Mysterious beings that protect the life of the forest.\\nThey have a green glow and look like they are one with the trees.\\nThey maintain the balance of the forest^ and protect it from outside invaders.\\nThey can use protective magic by borrowing the power of nature^ and communicate with the creatures of the forest.", "森の命を守る神秘的な存在。\\n緑色の光を帯び、木々と一体化した姿をしている。\\n森の均衡を保ち、外からの侵入者から森を守る。\\n自然の力を借りて守りの魔法を使い、森の生き物たちと心を通わせる。", "守护森林生命的神秘存在。\\n散发着绿色光芒，模样与树木融为一体。\\n它们维持着森林的平衡，保护森林不受外来入侵者侵扰。\\n能借助自然之力施展守护魔法，并与森林中的生灵心意相通。" }[language >= 0 && language <= 4 ? language : 0];
            case 20004: return new[] { "A mutant wolf that moves in packs and is agile.\\nTheir fur provides excellent camouflage in the forest^ and they are armed with sharp teeth and claws.\\nThey are also highly intelligent^ using strategy when hunting^ and they flee quickly when they sense danger.", "무리를 지어 다니며^ 민첩성을 지닌 변종 늑대.\\n그들의 털은 숲속에서 뛰어난 위장을 제공하며^ 날카로운 이빨과 발톱으로 무장하고 있다.\\n지능도 높아^ 사냥할 때 전략을 사용하며^ 위험을 감지하면 빠르게 도망치기도 한다.", "A mutant wolf that moves in packs and is agile.\\nTheir fur provides excellent camouflage in the forest^ and they are armed with sharp teeth and claws.\\nThey are also highly intelligent^ using strategy when hunting^ and they flee quickly when they sense danger.", "群れで行動する、俊敏な変異種の狼。\\nその毛皮は森の中で優れた迷彩となり、鋭い牙と爪で武装している。\\n知能も高く、狩りでは戦略を使い、危険を察するとすばやく逃げることもある。", "成群结队、身手敏捷的变异狼。\\n它们的皮毛在森林中是绝佳的伪装，并以锋利的牙齿和爪子武装自己。\\n它们智力也很高，狩猎时会运用战术，察觉危险时也会迅速逃走。" }[language >= 0 && language <= 4 ? language : 0];
